def write_csv(df,path):
 raw=df.to_csv(index=False).encode();temp=path.with_suffix('.csv.tmp');temp.write_bytes(raw)
 assert temp.read_bytes()==raw
 temp.replace(path)
 assert path.read_bytes()==raw

