cols=['symbol_index','entry_ms','exit_ms','side_sign','entry_price','quantity','initial_sl','r_distance','exit_price','gross_pnl','fees','funding_pnl','net_pnl','exit_reason_code','entry_equity','risk_usd','funding_proxy_count','root_unit_id','leg_index']
ledgers={};curves={};extra={};summaries=[]
for version in r:
 for period,m in r[version].items():
  z=np.load(OUT/f'{version}_{period}.npz');t=z['trades'];d=pd.DataFrame(t,columns=cols);d['symbol']=[symbols[int(x)] for x in d.symbol_index];d['side']=np.where(d.side_sign==1,'LONG','SHORT');d['entry_utc']=pd.to_datetime(d.entry_ms,unit='ms',utc=True).astype(str);d['exit_utc']=pd.to_datetime(d.exit_ms,unit='ms',utc=True).astype(str);d['hours_open']=(d.exit_ms-d.entry_ms)/3600000;d['net_r']=d.net_pnl/d.risk_usd;d['leg']=np.where(d.leg_index==0,'BASE','ADD');d['exit_reason']=d.exit_reason_code.map({3:'STOP',7:'CLOSED_CHANNEL_BREAK',8:'PERIOD_END'});d['slippage_drag']=.0002*d.quantity*(d.entry_price/(1+d.side_sign*.0002)+d.exit_price/(1-d.side_sign*.0002));d['ideal_gross']=d.gross_pnl+d.slippage_drag
  np.testing.assert_allclose(d.ideal_gross-d.slippage_drag-d.fees+d.funding_pnl,d.net_pnl,atol=1e-8)
  write_csv(d,OUT/f'{version}_{period}_trades.csv');ledgers[version,period]=d
  c=z['equity'];c=c[np.isfinite(c).all(axis=1)];c=np.vstack([[pd.Timestamp(dates[period][0],tz='UTC').timestamp()*1000,10000,10000],c]);c=pd.DataFrame(c,columns=['timestamp_ms','equity','balance']).drop_duplicates('timestamp_ms',keep='last').sort_values('timestamp_ms');c['utc']=pd.to_datetime(c.timestamp_ms,unit='ms',utc=True);c['peak']=c.equity.cummax();c['drawdown_pct']=(c.equity/c.peak-1)*100;write_csv(c,OUT/f'{version}_{period}_equity.csv');curves[version,period]=c
  neg=d[d.net_pnl<0];pos=d[d.net_pnl>0]
  e={'avg_win':float(pos.net_pnl.mean()),'avg_loss':float(neg.net_pnl.mean()),'slippage_drag':float(d.slippage_drag.sum()),'ideal_gross':float(d.ideal_gross.sum()),'median_hold_h':float(d.hours_open.median()),'negative_units':len(neg),'positive_units':len(pos),'exit_reasons':d.exit_reason.value_counts().to_dict(),'directions':{s:{'units':len(d[d.side==s]),'net':float(d[d.side==s].net_pnl.sum()),'win_rate':float((d[d.side==s].net_pnl>0).mean()*100)} for s in ['LONG','SHORT']}}
  worst=int(c.drawdown_pct.argmin());peak_index=int(c.iloc[:worst+1].equity.argmax());recovery=c.iloc[worst+1:];recovery=recovery[recovery.equity>=c.iloc[peak_index].equity];e['sampled_dd']={'peak_utc':str(c.iloc[peak_index].utc),'trough_utc':str(c.iloc[worst].utc),'pct':float(-c.iloc[worst].drawdown_pct),'recovery_utc':str(recovery.iloc[0].utc) if len(recovery) else None}
  extra[version,period]=e;summaries.append(dict(version=version,period=period,**{k:v for k,v in m.items() if k!='per_symbol'},**{k:v for k,v in e.items() if not isinstance(v,dict)}))
write_csv(pd.DataFrame(summaries),OUT/'comparison.csv')
